#!/bin/bash
# The 7 images of the Family Box Builder page (/explorations/family-box-builder), a DIFFERENT family in each scene, no text. The hero shows the four real bottles, the two science photos show a mom and a dad with their product, the other four are people only.
# FIRST ROUND of 2026-10-27 (2K and 4K, wide scenes): REJECTED by the owner, it looked artificial. The images in use come from the SECOND round, which used the All-in-1 recipe
# (1K, close simple scenes, the style block of the All-in-1 prompts), see PROMPTS.md. Do not re-run this script as is: use 1K and that recipe.
# Needs Gemini credits (two runs on 2026-10-27 failed with 402 "prepayment credits are depleted"). About $0.034 per 1K image and about $0.05 for the 2K hero, about $0.2 in total.
# Usage: bash tools/family-images.sh   (runs the 7 in parallel from the repo root; then inspect every image at full size: hands, arms, faces)
cd "$(dirname "$0")/.." || exit 1
BASE="Clean bright editorial lifestyle photo, soft natural window light, airy white and light blue palette, shallow depth of field, uncluttered, realistic everyday moment, candid. No text, no logos, no bottles or supplements anywhere. Every person has exactly two arms and two hands, natural faces."
# HERO: the family kitchen with the FOUR real bottles placed naturally (one per person: Kids' Multi, Teens' Daily Focus, Women's Nighttime Magnesium, Men's 3-in-1 Probiotic).
# The real cutouts go in as references (resized to 900 px) so the labels stay right. Written to family-hero.jpg at 2K (the bottles are small in the frame).
# AFTER it runs, the lid QA gate of the firstday-imagegen skill is mandatory: crop and enlarge every lid, and if one looks sunken use tools/lid-patch.sh.
TMP="$(mktemp -d)"
for f in kids-multi teens-brain woman-mag men-prob; do sips -Z 900 "public/assets/shop/$f.png" --out "$TMP/$f.png" >/dev/null; done
HERO_SCENE="Clean bright editorial lifestyle photo, portrait 4:5, soft natural morning window light, airy white and light blue palette, shallow depth of field, realistic everyday moment, candid. No text overlays, no logos other than the product labels. A busy family kitchen at breakfast, a mixed family of four: a tired but smiling mother in a denim shirt at the counter pouring orange juice, a father with short dark hair and light stubble leaning on the counter with a coffee mug in one hand and his phone in the other, a sleepy teenage girl with curly hair in a grey hoodie slumped over a bowl of cereal with her cheek on her hand, and a six year old boy with light brown hair at the wooden table pushing a small bowl of broccoli away. Four different real people, warm real life morning chaos. Each person has exactly two arms and two hands."
HERO_PRODUCTS="Show the four real First Day gummy bottles from the reference images, placed naturally in the scene the way a family leaves them around the kitchen, NOT lined up in a row: image 1 (green Kids multivitamin bottle) on the table next to the boy's bowl, image 2 (Teens daily focus bottle) near the teenage girl's elbow, image 3 (Women's nighttime magnesium bottle, red and purple) on the counter next to the mother and the juice, image 4 (Men's probiotic bottle) on the counter beside the father's coffee mug. Use each attached product exactly as is, keep every label, shape and color exactly the same. Each bottle is fully closed and opaque with a flat white lid, about 12 to 14 percent of the image width and 18 to 21 percent of the image height, roughly as tall as a drinking glass, standing upright on a surface, clearly visible and recognizable but not the center of attention. The lid top is the same bright white as the upper front band of the bottle, a perfectly flat smooth closed disc with no rim, no recess and no hole, not colored, not beige, not cream, not grey."
node tools/generate-image.mjs --out family-hero --aspect 4:5 --size 2K --ref "$TMP/kids-multi.png" --ref "$TMP/teens-brain.png" --ref "$TMP/woman-mag.png" --ref "$TMP/men-prob.png" --prompt "$HERO_SCENE $HERO_PRODUCTS" &
# SCIENCE TABS (owner rule: every image of that block is a PHOTO of a real person in an everyday moment WITH the product of that tab, not an infographic).
# Kids, Toddlers and Teens reuse the approved photos of the All-in-1 page (public/assets/custom/family-science-kids|toddlers|teens.jpg, copies of aio-kids-morning,
# aio-toddlers-picky and aio-teens-morning). Moms and Dads are generated here, 1:1, with the real cutout of the product as reference. After it runs: do the lid QA
# (crop and enlarge the lid, tools/lid-patch.sh if it looks sunken), check hands and faces, then add 'moms' and 'dads' to PHOTO_READY in src/data/familyStory.js.
for f in woman-multi men-multi; do sips -Z 900 "public/assets/shop/$f.png" --out "$TMP/$f.png" >/dev/null; done
SCI_BASE="Clean bright editorial lifestyle photo, square 1:1, soft natural morning window light, airy white and light blue palette, shallow depth of field, realistic everyday moment, candid. No text overlays. Use the attached product exactly as is, keep its label, shape and colors exactly the same. The bottle is fully closed and opaque with a flat white lid (the lid top is the same bright white as the upper front band, a perfectly flat smooth closed disc with no rim, no recess and no hole, not colored), standing upright on the counter, about 14 percent of the image width, clearly visible. Each person has exactly two arms and two hands, natural face."
node tools/generate-image.mjs --out family-science-moms --aspect 1:1 --size 2K --ref "$TMP/woman-multi.png" --prompt "$SCI_BASE A woman in her late thirties with shoulder length brown hair and a soft cream sweater stands at a bright kitchen counter in the morning holding a cup of coffee in one hand and a single small red gummy in the other hand, about to eat it, smiling a little tired but warm, the Women's multivitamin bottle from image 1 standing on the counter beside a fruit bowl and a school lunch box, the family kitchen softly out of focus behind her." &
node tools/generate-image.mjs --out family-science-dads --aspect 1:1 --size 2K --ref "$TMP/men-multi.png" --prompt "$SCI_BASE A man in his early forties with short dark hair and a light beard, in a grey t-shirt, stands at a bright kitchen counter in the morning with a packed gym bag at his feet, holding a glass of water in one hand and a single small gummy in the other hand, about to eat it, relaxed and confident, the Men's multivitamin bottle from image 1 standing on the counter next to his car keys, the family kitchen softly out of focus behind him." &
# WHY BLOCK ("A Toddler, A Teen And A Parent Cannot Share One Vitamin"): the family of five of different ages, each one with their OWN bottle (real cutouts as references).
for f in toddlers-multi kids-multi teens-multi; do sips -Z 900 "public/assets/shop/$f.png" --out "$TMP/$f.png" >/dev/null; done
node tools/generate-image.mjs --out family-why --aspect 1:1 --size 2K --ref "$TMP/toddlers-multi.png" --ref "$TMP/kids-multi.png" --ref "$TMP/teens-multi.png" --ref "$TMP/woman-multi.png" --ref "$TMP/men-multi.png" --prompt "Clean bright editorial lifestyle photo, square 1:1, soft natural window light, airy white and light blue palette, shallow depth of field, realistic everyday moment, candid. No text overlays. A family of five of clearly different ages gathered around a bright kitchen island, smiling and relaxed: a Black father in a blue shirt holding his two year old daughter on his hip, a nine year old boy with glasses, a fifteen year old girl with braids leaning on the counter, and the mother in a white linen shirt. Each person has exactly two arms and two hands, natural faces, the toddler is held by the father with one arm. On the island in front of each person stands their own First Day bottle from the reference images, in this order from left to right: image 1 (Toddlers multivitamin) in front of the toddler and father, image 2 (Kids multivitamin) in front of the boy, image 3 (Teens multivitamin) in front of the teenage girl, image 4 (Women's multivitamin) in front of the mother, and image 5 (Men's multivitamin) next to the father. Five different bottles, each one clearly its own, standing upright and a little apart from each other, NOT lined up like a product shot. Use each attached product exactly as is, keep every label, shape and color exactly the same. Each bottle is fully closed and opaque with a flat white lid (same bright white as the upper front band, a perfectly flat smooth closed disc with no rim, no recess and no hole, not colored), about 13 percent of the image width, clearly visible. Lid QA after it runs." &
node tools/generate-image.mjs --out family-timeline-1 --aspect 4:3 --prompt "$BASE A Hispanic family at a sunny breakfast table, 4:3 landscape: a mother, a father, a five year old boy and a nine year old girl happily sharing fruit, yogurt and toast, the children eating well, relaxed and cheerful morning." &
node tools/generate-image.mjs --out family-timeline-2 --aspect 4:3 --prompt "$BASE A South Asian mother and her fifteen year old daughter laughing together while cooking at a bright kitchen island, 4:3 landscape, afternoon light, relaxed, the teen looks easy and cheerful, chopping vegetables side by side." &
node tools/generate-image.mjs --out family-timeline-3 --aspect 4:3 --prompt "$BASE An East Asian family of four around a dinner table in a warm home, 4:3 landscape: parents, a ten year old boy and a fourteen year old girl passing a big colorful salad bowl and plates of roasted vegetables, smiling and chatting, the whole table feels connected." &
wait
